import{_ as a,o as s,c as t,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"8. Command Line Basics for C Developers","description":"The Little Book of C — 8. Command Line Basics for C Developers","frontmatter":{"title":"8. Command Line Basics for C Developers","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Getting Started"],"description":"The Little Book of C — 8. Command Line Basics for C Developers","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":8,"sidebarWeight":8,"lang":"en-US","alternateEn":"/posts/c教程/en-US/01-Getting Started/008-Command Line Basics for C Developers","alternateZh":"/posts/c教程/zh-CN/01-入门/008-Command Line Basics for C Developers"},"headers":[],"relativePath":"posts/c教程/en-US/01-Getting Started/008-Command Line Basics for C Developers.md","filePath":"posts/c教程/en-US/01-Getting Started/008-Command Line Basics for C Developers.md","lastUpdated":1790163617000}'),o={name:"posts/c教程/en-US/01-Getting Started/008-Command Line Basics for C Developers.md"};function i(l,e,p,c,d,r){return s(),t("div",null,[...e[0]||(e[0]=[n(`<p>[中文版本](/posts/c教程/zh-CN/01-入门/008-Command Line Basics for C Developers)</p><p>C was born in the Unix world, and the command line is its natural home. If you can move comfortably in the terminal, you’ll understand what your tools are doing, compiling, linking, and running programs directly. This section gives you the essential commands you’ll need to build and explore C projects like a real systems programmer.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>Let’s start with a quick refresher using a simple file<code>hello.c</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello from the terminal!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>To build and run it from the command line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.c -o hello</span></span>
<span class="line"><span>./hello</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello from the terminal!</span></span></code></pre></div><p>That’s the full cycle: write → compile → run. Now let’s look at the basic tools that make that process smoother.</p><h4 id="essential-command-line-tools" tabindex="-1">Essential Command Line Tools <a class="header-anchor" href="#essential-command-line-tools" aria-label="Permalink to &quot;Essential Command Line Tools&quot;">​</a></h4><p><code>ls</code>– List files in the current directory</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ls</span></span></code></pre></div><p>You’ll see files like<code>hello.c</code>,<code>hello.o</code>, or<code>hello</code>.</p><p><code>pwd</code>– Print the current working directory</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pwd</span></span></code></pre></div><p><code>cd</code>– Change directories</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd projects/c_programs</span></span></code></pre></div><p><code>cat</code>– Display file contents quickly</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat hello.c</span></span></code></pre></div><p><code>rm</code>– Remove files</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm hello</span></span></code></pre></div><p><code>clear</code>– Clear your terminal screen</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clear</span></span></code></pre></div><p><code>man</code>– Read the manual for a command</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>man gcc</span></span></code></pre></div><p>Press<code>q</code> to exit.</p><p><code>echo</code>– Print a message or variable</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &quot;Compiling C!&quot;</span></span></code></pre></div><p><code>touch</code>– Create a new empty file</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>touch main.c</span></span></code></pre></div><p><code>gcc</code>– Compile your C source code</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -o main</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>The command line isn’t just for building code, it teaches you how your tools actually work. In C, there’s no hidden environment running behind a button click. Each command you type does exactly one job, and understanding those jobs gives you full control.</p><ul><li>You see the build process directly.</li><li>You control where outputs go.</li><li>You can chain commands for automation.</li></ul><p>This mindset, knowing what happens under the hood, is what makes C programmers comfortable working close to the machine.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Navigate and build manually:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir myfirstc</span></span>
<span class="line"><span>cd myfirstc</span></span>
<span class="line"><span>touch hello.c</span></span></code></pre></div><p>Add code with your favorite text editor (like<code>nano hello.c</code>), then compile and run.</p><p>Use compiler flags:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -Wall -O2 hello.c -o hello</span></span>
<span class="line"><span>./hello</span></span></code></pre></div><ul><li><code>-Wall</code> enables warnings.</li><li><code>-O2</code> applies optimization.</li></ul><p>Use output redirection:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello &gt; output.txt</span></span>
<span class="line"><span>cat output.txt</span></span></code></pre></div><p>Explore commands interactively:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>man ls</span></span>
<span class="line"><span>man gcc</span></span></code></pre></div><p>Read a few lines, knowing how to find help is as important as coding itself.</p><p>C and the command line grew up together. Once you get comfortable typing and compiling by hand, you’ll start to feel how programs, files, and processes fit together. That’s the real start of systems programming, not just writing code, but commanding the computer directly.</p>`,50)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
